def glbdoc(path):
 b=pathlib.Path(path).read_bytes(); import struct
 _,v,l=struct.unpack_from('<4sII',b,0); pos=12;doc=None
 while pos<len(b):
  n,t=struct.unpack_from('<II',b,pos);pos+=8;c=b[pos:pos+n];pos+=n
  if t==0x4e4f534a:doc=json.loads(c.decode().rstrip('\0 \n\r\t'))
 return doc
